<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Animated Solar System</title>
<style>
  body, html { margin:0; height:100%; background:black; overflow:hidden; }
  canvas { display:block; width:100%; height:100%; }
</style>
</head>
<body>
<canvas id="canvas"></canvas>
<script>
(() => {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = window.innerWidth;
  const height = canvas.height = window.innerHeight;
  const cx = width / 2, cy = height / 2;

  // Starfield
  const stars = Array.from({length: 200}, () => ({
    x: Math.random() * width,
    y: Math.random() * height,
    size: Math.random() * 1.5 + 0.5,
    brightness: Math.random() * 0.5 + 0.5
  }));

  // Sun and planets data
  const sun = { radius: 30, color: '#f39c12' };
  const planets = [
    {name:'Mercury', radius:5, color:'#a8a8a8', orbit:60, speed:1.0},
    {name:'Venus',   radius:8, color:'#e5b973', orbit:90, speed:0.8},
    {name:'Earth',   radius:9, color:'#3498db', orbit:120, speed:0.7},
    {name:'Mars',    radius:7, color:'#e74c3c', orbit:150, speed:0.6},
    {name:'Jupiter', radius:16, color:'#d35400', orbit:200, speed:0.4},
    {name:'Saturn',  radius:14, color:'#f1c40f', orbit:240, speed:0.3},
    {name:'Uranus',  radius:12, color:'#1abc9c', orbit:280, speed:0.2},
    {name:'Neptune', radius:12, color:'#9b59b6', orbit:320, speed:0.1}
  ];

  // Helper to draw text with shadow
  const drawLabel = (text, x, y) => {
    ctx.font = '12px Arial';
    ctx.fillStyle = 'white';
    ctx.textBaseline = 'top';
    ctx.fillText(text, x + 2, y + 2);
  };

  const animate = (time) => {
    ctx.clearRect(0, 0, width, height);

    // Draw starfield
    ctx.fillStyle = 'black';
    ctx.fillRect(0,0,width,height);
    ctx.fillStyle = 'white';
    stars.forEach(s=>{
      ctx.globalAlpha = s.brightness;
      ctx.fillRect(s.x, s.y, s.size, s.size);
    });
    ctx.globalAlpha = 1;

    // Draw Sun
    ctx.fillStyle = sun.color;
    ctx.beginPath();
    ctx.arc(cx, cy, sun.radius, 0, Math.PI*2);
    ctx.fill();

    // Draw planets
    planets.forEach(p=>{
      const angle = (time * p.speed * 0.0001) % (Math.PI*2);
      const x = cx + Math.cos(angle) * p.orbit;
      const y = cy + Math.sin(angle) * p.orbit;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(x, y, p.radius, 0, Math.PI*2);
      ctx.fill();
      drawLabel(p.name, x, y);
    });

    requestAnimationFrame(animate);
  };

  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
```
This file creates a canvas that draws a static starfield and animates the Sun and eight planets orbiting the Sun at different speeds using `requestAnimationFrame`.
